func escapeJSONPointerToken(token string) string {
	token = strings.ReplaceAll(token, "~", "~0")
	return strings.ReplaceAll(token, "/", "~1")
}

// decodedJSONType returns the JSON category retained by Decoder.UseNumber.
func decodedJSONType(value any) string {
	switch value.(type) {
	case bool:
		return "boolean"
	case json.Number:
		return "number"
	case string:
		return "string"
	case []any:
		return "array"
	case map[string]any:
		return "object"
	default:
		panic(fmt.Sprintf("unsupported decoded JSON value %T", value))
	}
}

// generatedUnmarshalJSONType reduces encoding/json's detailed value label to
// the stable JSON category carried by FieldIssue.
func generatedUnmarshalJSONType(value string) string {
	category, _, _ := strings.Cut(value, " ")
	switch category {
	case "array", "bool", "number", "object", "string":
		if category == "bool" {
			return "boolean"
		}
		return category
	default:
		return ""
	}
}

// invalidGeneratedFieldTypeError reports a raw JSON category that conflicts
// with the generated schema and attaches that schema path's description.
func invalidGeneratedFieldTypeError(field, expected, actual, description string) error {
	var descriptions map[string]string
	if description != "" {
		descriptions = map[string]string{field: description}
	}
	return tools.NewValidationError(
		fmt.Sprintf("field %q must be %s, got %s", field, expected, actual),
		[]*tools.FieldIssue{
			{
				Field:            field,
				Constraint:       "invalid_field_type",
				ExpectedJSONType: expected,
				ActualJSONType:   actual,
			},
		},
		descriptions,
	)
}

// invalidJSONUnionDiscriminator reports an absent, non-string or undeclared
// branch selector at its actual JSON path, so callers can correct that field.
func invalidJSONUnionDiscriminator(field string, got any, present bool, allowed []string) error {
	constraint := "invalid_enum_value"
	if !present {
		constraint = "missing_field"
	} else if _, ok := got.(string); !ok {
		return invalidGeneratedFieldTypeError(field, "string", decodedJSONType(got), "")
	}
	return tools.NewValidationError(
		fmt.Sprintf("field %q must select a declared union branch", field),
		[]*tools.FieldIssue{
			{Field: field, Constraint: constraint, Allowed: allowed},
		},
		nil,
	)
}

// missingJSONField reports an absent required JSON property at its generated
// path, so callers receive the same field contract for every union mapping.
func missingJSONField(field string) error {
	return tools.NewValidationError(
		fmt.Sprintf("field %q is required", field),
		[]*tools.FieldIssue{
			{Field: field, Constraint: "missing_field"},
		},
		nil,
	)
}

func unknownJSONFieldError(path, field string, allowed []string) error {
	issueField := generatedJSONChildPath(path, field, false)
	return tools.NewValidationError(
		fmt.Sprintf("unknown field %q", issueField),
		[]*tools.FieldIssue{
			{
				Field:      issueField,
				Constraint: "unknown_field",
				Allowed:    append([]string(nil), allowed...),
			},
		},
		nil,
	)
}

